import colorsys

def frange(start, stop, step):
    while start <= stop:
        yield start
        start += step

def assertTripleEqual(tr1, tr2):
    assert len(tr1) == 3, ('assertEqual', len(tr1), 3)
    assert len(tr2) == 3, ('assertEqual', len(tr2), 3)
    assert round(tr1[0] - tr2[0], 7) == 0, ('assertAlmostEqual', tr1[0], tr2[0])
    assert round(tr1[1] - tr2[1], 7) == 0, ('assertAlmostEqual', tr1[1], tr2[1])
    assert round(tr1[2] - tr2[2], 7) == 0, ('assertAlmostEqual', tr1[2], tr2[2])

def _t():
    for r in frange(0.0, 1.0, 0.2):
        for g in frange(0.0, 1.0, 0.2):
            for b in frange(0.0, 1.0, 0.2):
                rgb = (r, g, b)
                assertTripleEqual(rgb, colorsys.hsv_to_rgb(*colorsys.rgb_to_hsv(*rgb)))
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

